const RECEIPT_CSS = ".sheet {\r\n  position: relative;\r\n  background: #fff;\r\n  color: #1a1a1a;\r\n  box-sizing: border-box;\r\n  overflow: hidden;\r\n}\r\n\r\n.sheet * { box-sizing: border-box; }\r\n\r\n.sheet.invoice {\r\n  width: min(820px, 100%);\r\n  min-height: 1040px;\r\n  margin: 0 auto;\r\n  padding: 42px 48px 36px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  box-shadow: 0 18px 50px rgba(50, 36, 12, 0.08);\r\n}\r\n\r\n.sheet.compact {\r\n  width: min(420px, 100%);\r\n  margin: 0 auto;\r\n  padding: 28px 26px 32px;\r\n  box-shadow: 0 18px 50px rgba(50, 36, 12, 0.08);\r\n}\r\n\r\n.ornament {\r\n  position: absolute;\r\n  width: 280px;\r\n  height: 340px;\r\n  pointer-events: none;\r\n  z-index: 0;\r\n}\r\n\r\n.ornament-tr { top: -10px; right: -30px; }\r\n.ornament-bl { left: -40px; bottom: -20px; transform: rotate(180deg); }\r\n\r\n.wm {\r\n  position: absolute;\r\n  left: 50%;\r\n  top: 46%;\r\n  transform: translate(-50%, -50%);\r\n  font-size: 78px;\r\n  letter-spacing: 0.14em;\r\n  color: rgba(176, 148, 92, 0.14);\r\n  font-weight: 700;\r\n  white-space: nowrap;\r\n  pointer-events: none;\r\n  z-index: 0;\r\n  font-family: \"PMingLiU\", \"Microsoft JhengHei\", Palatino, serif;\r\n}\r\n\r\n.sheet > *:not(.ornament):not(.wm) { position: relative; z-index: 1; }\r\n\r\n.sheet-top {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-start;\r\n  gap: 24px;\r\n}\r\n\r\n.sheet-logo { width: 188px; height: auto; display: block; }\r\n\r\n.sheet h1 {\r\n  margin: 18px 0 0;\r\n  font-family: \"Palatino Linotype\", Palatino, \"PMingLiU\", \"Microsoft JhengHei\", serif;\r\n  font-size: 48px;\r\n  font-weight: 500;\r\n  letter-spacing: 0.02em;\r\n  line-height: 1;\r\n}\r\n\r\n.sheet.compact h1 {\r\n  margin: 8px 0 0;\r\n  text-align: center;\r\n  font-size: 28px;\r\n}\r\n\r\n.sheet.compact .sheet-logo { width: 150px; margin: 0 auto 4px; }\r\n\r\n.sheet-meta {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  gap: 24px;\r\n  margin: 28px 0 26px;\r\n  font-size: 15px;\r\n  line-height: 1.55;\r\n}\r\n\r\n.sheet-meta p { margin: 0; }\r\n.sheet-to { max-width: 62%; }\r\n.addr { white-space: pre-line; }\r\n.sheet-date { text-align: right; white-space: nowrap; }\r\n.sheet-date .orderno { margin-top: 8px; }\r\n\r\n.sheet-table {\r\n  width: 100%;\r\n  border-collapse: collapse;\r\n  table-layout: fixed;\r\n  border: 1.5px solid #1c1c1c;\r\n}\r\n\r\n.sheet-table th,\r\n.sheet-table td {\r\n  border: 1px solid #1c1c1c;\r\n  padding: 11px 10px;\r\n  vertical-align: top;\r\n  font-size: 14px;\r\n}\r\n\r\n.sheet-table th {\r\n  font-weight: 650;\r\n  letter-spacing: 0.08em;\r\n  text-align: center;\r\n  font-size: 13px;\r\n}\r\n\r\n.c-item { width: 68px; text-align: center; }\r\n.c-qty { width: 110px; text-align: center; }\r\n.c-amt { width: 150px; text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }\r\n.desc { white-space: pre-line; text-align: left; }\r\n\r\n.sheet-total {\r\n  margin-left: auto;\r\n  width: 280px;\r\n  display: grid;\r\n  grid-template-columns: 1fr 150px;\r\n  align-items: stretch;\r\n}\r\n\r\n.sheet-total span {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: flex-end;\r\n  padding: 8px 12px;\r\n  font-weight: 650;\r\n}\r\n\r\n.sheet-total strong {\r\n  border: 1.5px solid #1c1c1c;\r\n  border-top: 0;\r\n  padding: 8px 10px;\r\n  text-align: right;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.sheet-notes {\r\n  margin: 28px 0 0;\r\n  padding-left: 18px;\r\n  font-size: 14px;\r\n}\r\n\r\n.sheet-notes li { margin: 4px 0; }\r\n\r\n.sheet-foot {\r\n  margin-top: auto;\r\n  padding-top: 36px;\r\n  text-align: center;\r\n  font-size: 13px;\r\n  letter-spacing: 0.01em;\r\n}\r\n\r\n.sheet.compact .center { text-align: center; }\r\n.sheet.compact .muted { color: #5c564c; font-size: 12px; margin: 4px 0 0; white-space: pre-line; }\r\n.rule { height: 1px; background: #1c1c1c; margin: 14px 0; }\r\n.compact-meta { font-size: 13px; line-height: 1.55; }\r\n.compact-meta p { margin: 0; }\r\n.compact-table { width: 100%; border-collapse: collapse; margin-top: 12px; }\r\n.compact-table th, .compact-table td { text-align: left; font-size: 13px; padding: 7px 0; border-bottom: 1px solid #e6e0d6; vertical-align: top; }\r\n.compact-table .num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }\r\n.compact-total { display: flex; justify-content: space-between; font-weight: 700; margin-top: 10px; font-size: 16px; }\r\n.balance-list { margin: 14px 0 0; padding: 0; list-style: none; font-size: 13px; }\r\n.balance-list li { display: flex; justify-content: space-between; gap: 12px; padding: 4px 0; border-bottom: 1px dashed #e6e0d6; }\r\n.sheet.compact .sheet-notes { margin-top: 16px; }\r\n.section-label { margin: 22px 0 8px; font-size: 13px; letter-spacing: 0.14em; text-transform: uppercase; }\r\n\r\nbody.receipt-export { margin: 0; background: #e7e0d4; font-family: \"Segoe UI\", \"Microsoft JhengHei\", sans-serif; }\r\nbody.receipt-export .sheet { margin: 24px auto; }\r\n\r\n@media print {\r\n  body.receipt-export { background: white; }\r\n  .sheet { box-shadow: none !important; margin: 0 !important; }\r\n  .sheet.invoice { min-height: 250mm; width: auto; }\r\n  @page { size: A4; margin: 12mm; }\r\n}\r\n";
